21	const StaggerList = ({
22	  children,
23	  stagger = 0.05,
24	  duration = 0.25,
25	  direction = "up",
26	  distance = 10,
27	  className,
28	}: StaggerListProps) => {
29	  const dir = directionMap[direction];
30	
31	  return (
32	    <motion.div
33	      className={className}
34	      initial="hidden"
35	      animate="visible"
